    public double evaluate(double[] x) {
        // check input
        if (x.length != 6) {
            System.err.println("ERROR - Wrong Input Vector Length");
            return Double.NaN;
        }
        // normalize input
        double[] xn = new double[6];
        for (int i = 0; i < 6; i++) {
            xn[i] = (x[i]-xRange[i][0])/(xRange[i][1]-xRange[i][0]);
        }
        // linear combination
        double yn = 0.0D;
        for (int i = 0; i < alpha.length; i++) {
            yn += alpha[i] * computeCovariance(getDistance(xn, xData[i]));
        }
        // scale output
        double y = yRange[0]+(yRange[1]-yRange[0])*yn;
        return y;
    }

    private double computeCovariance(double distance) {
        final double t2 = 5.0D * distance;
        final double t = Math.sqrt(t2);
        return signalVariance * (1.0D + t + t2 / 3.0D) * Math.exp(-t);
    }

    private double getDistance(double[] xp, double[] xq) {
        double res = 0.0;
        for (int i = 0; i < xp.length; i++) {
            final double d = (xp[i] - xq[i]) / lengthScale[i];
            res += d * d;
        }
        return res;
    }
